typedef struct {
    bool high;
    double mu, height;
    int minute, label;
} Extremum;
double prediction(const Model *model, double time) {
    double out = model->coefficients[0];
    for (int k = 0; k < model->count; ++k) {
        double theta = angle(model->speeds[k], time);
        out += model->coefficients[2 * k + 1] * cos(theta) +
               model->coefficients[2 * k + 2] * sin(theta);
    }
    return out;
}
Extrema extrema(const Model *model, int start, int length, int grid) {
    int count = length * 60 / grid;
    double *values = allocate((size_t)count + 1, sizeof(double));
    for (int j = 0; j <= count; ++j)
        values[j] = prediction(model, (double)(60 * start + j * grid) / 60);
    Extrema out = {allocate((size_t)count, sizeof(Extremum)), 0};
    for (int j = 1; j < count; ++j) {
        bool high = values[j - 1] < values[j] && values[j] > values[j + 1],
             low = values[j - 1] > values[j] && values[j] < values[j + 1];
        if (!high && !low)
            continue;
        double delta = (values[j - 1] - values[j + 1]) /
                       (2 * (values[j - 1] - 2 * values[j] + values[j + 1])),
               mu = 60 * start + j * grid + delta * grid,
               height = values[j] - (values[j - 1] - values[j + 1]) * delta / 4;
        out.data[out.count++] = (Extremum){high, mu, height, 0, 0};
    }
    return out;
    for (int i = 0; i <= p->length; ++i)
        s->hourly[i] = prediction(s->model, p->start + i);
    s->waters = extrema(s->model, p->start, p->length, p->grid);
    while (s->waters.count >= 2) {
        int first = 0;
        double minimum = fabs(s->waters.data[0].height - s->waters.data[1].height);
        for (int i = 1; i + 1 < s->waters.count; ++i) {
            double difference = fabs(s->waters.data[i].height - s->waters.data[i + 1].height);
            if (difference < minimum) {
                minimum = difference;
                first = i;
            }
        }
        if (minimum >= p->min_range)
            break;
        memmove(s->waters.data + first, s->waters.data + first + 2,
                (size_t)(s->waters.count - first - 2) * sizeof(Extremum));
        s->waters.count -= 2;
    }
    for (int i = 0; i < s->waters.count; ++i) {
        Extremum *water = &s->waters.data[i];
        water->minute = (int)floor(water->mu + 0.5);
    for (int i = 0; i < s->waters.count; ++i) {
        Extremum water = s->waters.data[i];
        line(&s->extremes, "%s %s %s change=%s", datetime(water.minute, p->epoch_day),
             labels[water.label], real(water.height, 3),
             i ? real(water.height - s->waters.data[i - 1].height, 3) : "none");
